; ---------------------------------------------------------------
; void __near__ load_room (void)
; ---------------------------------------------------------------

.segment	"CODE"

.proc	_load_room: near

.segment	"CODE"

;
; ppu_off();
;
	jsr     _ppu_off
;
; vram_adr(NAMETABLE_A);
;
	ldx     #$20
	lda     #$00
	jsr     _vram_adr
;
; if (game_mode == MODE_TITLE)
;
	lda     _game_mode
	bne     L2F5F
;
; vram_unrle(title);
;
	lda     #<(_title)
	ldx     #>(_title)
	jsr     _vram_unrle
;
; else if (game_mode == MODE_OPTIONS)
;
	jmp     _ppu_on_all
L2F5F:	lda     _game_mode
	cmp     #$01
	bne     L2F60
;
; vram_unrle(settings);
;
	lda     #<(_settings)
	ldx     #>(_settings)
	jsr     _vram_unrle
;
; else
;
	jmp     _ppu_on_all
;
; for (largeindex = 0; largeindex < 1024; ++largeindex)
;
L2F60:	lda     #$00
	sta     _largeindex
	sta     _largeindex+1
L1AC3:	ldx     _largeindex+1
	cpx     #$04
	bcs     L1AC4
;
; vram_put(map_ptr[largeindex]);
;
	lda     _map_ptr
	clc
	adc     _largeindex
	sta     ptr1
	lda     _map_ptr+1
	adc     _largeindex+1
	sta     ptr1+1
	ldy     #$00
	lda     (ptr1),y
	jsr     _vram_put
;
; for (largeindex = 0; largeindex < 1024; ++largeindex)
;
	inc     _largeindex
	bne     L1AC3
	inc     _largeindex+1
	jmp     L1AC3
;
; ppu_on_all();
;
L1AC4:	jmp     _ppu_on_all

.endproc

